     1→<?php
     2→
     3→declare(strict_types=1);
     4→
     5→namespace Cpsit\QualityTools\Traits;
     6→
     7→use Cpsit\QualityTools\Exception\ConfigurationFileNotFoundException;
     8→use Cpsit\QualityTools\Exception\ConfigurationFileNotReadableException;
     9→use Cpsit\QualityTools\Exception\ConfigurationLoadException;
    10→use Symfony\Component\Yaml\Yaml;
    11→
    12→/**
    13→ * Trait providing YAML file loading functionality.
    14→ *
    15→ * This trait provides methods to load and parse YAML configuration files
    16→ * with proper validation and error handling.
    17→ */
    18→trait YamlFileLoaderTrait
    19→{
    20→    /**
    21→     * Load and parse YAML configuration file with validation.
    22→     *
    23→     * @param string $path The path to the YAML file
    24→     *
    25→     * @throws ConfigurationLoadException When the file cannot be loaded or is invalid
    26→     *
    27→     * @return array The parsed and validated configuration data
    28→     */
    29→    protected function loadYamlFile(string $path): array
    30→    {
    31→        try {
    32→            $content = $this->readConfigurationFile($path);
    33→
    34→            // Apply environment variable interpolation
    35→            $content = $this->interpolateEnvironmentVariables($content);
    36→
    37→            $data = Yaml::parse($content);
    38→            if (!\is_array($data)) {
    39→                throw new ConfigurationLoadException('Configuration file must contain valid YAML data', $path);
    40→            }
    41→
    42→            // Validate configuration if validator is available
    43→            if (isset($this->validator)) {
    44→                $validationResult = $this->validator->validateSafe($data);
    45→                if (!$validationResult->isValid()) {
    46→                    $errors = implode("\n", $validationResult->getErrors());
    47→                    throw new ConfigurationLoadException("Invalid configuration:\n$errors", $path);
    48→                }
    49→            }
    50→
    51→            return $data;
    52→        } catch (ConfigurationFileNotFoundException|ConfigurationFileNotReadableException $e) {
    53→            throw $e;
    54→        } catch (\Exception $e) {
    55→            throw new ConfigurationLoadException('Failed to load YAML configuration: ' . $e->getMessage(), $path, $e);
    56→        }
    57→    }
    58→}
    59→

